import{_ as l,W as i,s as d,u as o,ah as u,I as t,w as n,Z as e,A as p}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const k=JSON.parse('{"title":"使用 df 命令查看 Linux 上的可用磁盘空间 | LCTT x X-CMD","titleTemplate":false,"description":"使用 df 命令查看 Linux 上的可用磁盘空间 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"使用 df 命令查看 Linux 上的可用磁盘空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 df 命令查看 Linux 上的可用磁盘空间 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210729 Use df to check free disk space on Linux","title":"使用 df 命令查看 Linux 上的可用磁盘空间","tag":"202108"},"relativePath":"202108/20210729 Use df to check free disk space on Linux.md","filePath":"[post].md"}'),r={name:"202108/20210729 Use df to check free disk space on Linux.md"};function f(c,s,m,h,x,v){const a=i("Link");return o(),d("div",null,[s[18]||(s[18]=u(`<h1 id="使用-df-命令查看-linux-上的可用磁盘空间" tabindex="-1">使用 df 命令查看 Linux 上的可用磁盘空间 <a class="header-anchor" href="#使用-df-命令查看-linux-上的可用磁盘空间" aria-label="Permalink to 使用 df 命令查看 Linux 上的可用磁盘空间">​</a></h1><blockquote><p>利用 df 命令查看 Linux 磁盘还剩多少空间。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/04/110742netskjccb5vzvujk.jpg" alt=""></p><p>磁盘空间已经不像计算机早期那样珍贵，但无论你有多少磁盘空间，总有耗尽的可能。计算机需要一些磁盘空间才能启动运行，所以为了确保你没有在无意间用尽了所有的硬盘空间，偶尔检查一下是非常必要的。在 Linux 终端，你可以用 <code>df</code> 命令来做这件事。</p><p><code>df</code> 命令可以显示文件系统中可用的磁盘空间。</p><p>要想使输出结果易于阅读，你可以加上 <code>--human-readable</code>（或其简写 <code>-h</code>）选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ df --human-readable</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/sda1       1.0T  525G  500G  52% /</span></span></code></pre></div><p>在这个例子中，计算机的磁盘已经用了 52%，还有 500 GB 可用空间。</p><p>由于 Linux 从整体上看待所有挂载设备的文件系统，<code>df</code> 命令会展示出连接到计算机上的每个存储设备的详细信息。如果你有很多磁盘，那么输出结果将会反映出来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ df --human-readable</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/root       110G   45G   61G  43% /</span></span>
<span class="line"><span>devtmpfs         12G     0   12G   0% /dev</span></span>
<span class="line"><span>tmpfs            12G  848K   12G   1% /run</span></span>
<span class="line"><span>/dev/sda1       1.6T  1.3T  191G  87% /home</span></span>
<span class="line"><span>/dev/sdb1       917G  184G  687G  22% /penguin</span></span>
<span class="line"><span>/dev/sdc1        57G   50G  4.5G  92% /sneaker</span></span>
<span class="line"><span>/dev/sdd1       3.7T  2.4T  1.3T  65% /tux</span></span></code></pre></div><p>在这个例子中，计算机的 <code>/home</code> 目录已经用了 87%，剩下 191 GB 的可用空间。</p><h3 id="查看总的可用磁盘空间" tabindex="-1">查看总的可用磁盘空间 <a class="header-anchor" href="#查看总的可用磁盘空间" aria-label="Permalink to 查看总的可用磁盘空间">​</a></h3><p>如果你的文件系统确实很复杂，而你希望看到所有磁盘的总空间，可以使用 <code>--total</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ df --human-readable --total</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/root       110G   45G   61G  43% /</span></span>
<span class="line"><span>devtmpfs         12G     0   12G   0% /dev</span></span>
<span class="line"><span>tmpfs            12G  848K   12G   1% /run</span></span>
<span class="line"><span>/dev/sda1       1.6T  1.3T  191G  87% /home</span></span>
<span class="line"><span>/dev/sdb1       917G  184G  687G  22% /penguin</span></span>
<span class="line"><span>/dev/sdc1        57G   50G  4.5G  92% /sneaker</span></span>
<span class="line"><span>/dev/sdd1       3.7T  2.4T  1.3T  65% /tux</span></span>
<span class="line"><span>total           6.6T  4.0T  2.5T  62% -</span></span></code></pre></div><p>输出的最后一行展示了文件系统的总空间、已用总空间、可用总空间。</p><h3 id="查看磁盘空间使用情况" tabindex="-1">查看磁盘空间使用情况 <a class="header-anchor" href="#查看磁盘空间使用情况" aria-label="Permalink to 查看磁盘空间使用情况">​</a></h3>`,16)),t("p",null,[s[1]||(s[1]=n("如果你想大概了解哪些文件占用了磁盘空间，请阅读我们关于 ")),e(a,{href:"https://opensource.com/article/21/7/check-used-disk-space-linux-du"},{default:p(()=>s[0]||(s[0]=[n("du 命令")])),_:1}),s[2]||(s[2]=n(" 的文章。"))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[4]||(s[4]=n("via: ")),e(a,{href:"https://opensource.com/article/21/7/check-disk-space-linux-df"},{default:p(()=>s[3]||(s[3]=[n("https://opensource.com/article/21/7/check-disk-space-linux-df")])),_:1})]),t("p",null,[s[9]||(s[9]=n("作者：")),e(a,{href:"https://opensource.com/users/seth"},{default:p(()=>s[5]||(s[5]=[n("Seth Kenlon")])),_:1}),s[10]||(s[10]=n(" 选题：")),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>s[6]||(s[6]=[n("lujun9972")])),_:1}),s[11]||(s[11]=n(" 译者：")),e(a,{href:"https://github.com/piaoshi"},{default:p(()=>s[7]||(s[7]=[n("piaoshi")])),_:1}),s[12]||(s[12]=n(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:p(()=>s[8]||(s[8]=[n("wxy")])),_:1})]),t("p",null,[s[15]||(s[15]=n("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[13]||(s[13]=[n("LCTT")])),_:1}),s[16]||(s[16]=n(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:p(()=>s[14]||(s[14]=[n("Linux中国")])),_:1}),s[17]||(s[17]=n(" 荣誉推出"))])])}const g=l(r,[["render",f]]);export{k as __pageData,g as default};
